scaffold.Post:
CREATE TABLE "users" ("user_id" INTEGER PRIMARY KEY AUTOINCREMENT, "email" TEXT NOT NULL, "display_name" TEXT) STRICT;
CREATE UNIQUE INDEX "ux_users_email" ON "users" ("email");
CREATE TABLE "posts" ("post_id" INTEGER PRIMARY KEY AUTOINCREMENT, "author_id" INTEGER NOT NULL, "title" TEXT NOT NULL, FOREIGN KEY ("author_id") REFERENCES "users" ("user_id")) STRICT;

scaffold.Product:
CREATE TABLE `products` (`product_id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, `price` DECIMAL(12,2) NOT NULL, `code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL, `token` UUID NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `payload` JSON NOT NULL, `active` BOOLEAN NOT NULL, `description` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL, `image` BLOB NOT NULL) ENGINE=InnoDB;
CREATE UNIQUE INDEX `ux_products_price` ON `products` (`price`);
CREATE UNIQUE INDEX `ux_products_code` ON `products` (`code`);
CREATE INDEX `description_prefix` ON `products` (`description`(16));
